[workspace]
resolver = "2"
members = ["crates/*"]

[workspace.dependencies]
actix-cors = "0.6"
actix-files = "0.6"
actix-multipart = "0.7"
actix-web = "4"
async-trait = "0.1.83"
chrono = { version = "0.4.38", features = ["serde"] }
confik = "0.11"
dotenvy = "0.15"
env_logger = "0.10.0"
tracing = "0.1"
tracing-subscriber = { version = "0.3", features = ["json", "env-filter"] }
tracing-actix-web = "0.7"
futures-util = "0.3.30"
rand = "0.8.5"
rust_decimal = "1.36.0"
rust_decimal_macros = "1.36.0"
serde = { version = "1", features = ["derive"] }
serde_json = { version = "1.0.117", features = ["raw_value"] }
sqlx = { version = "0.8.2", features = ["postgres", "runtime-tokio", "bigdecimal", "rust_decimal", "time", "uuid", "chrono"] }
tokio = { version = "1.10.0", features = ["full"] }
tokio-tungstenite = { version = "0.24.0", features = ["native-tls"] }
uuid = { version = "1.10.0", features = ["v4", "v5", "serde"] }

use crate::engine::orderbook::OrderBook;
use crate::types::engine::{
    Asset, AssetPair, CancelAllOrders, CancelOrder, CreateOrder, GetDepth, GetOpenOrder,
    GetOpenOrders, Order, OrderSide, ProcessOrderResult,
};
use db_processor::query::get_latest_trade_id_from_db;
use pg_queue::PgQueueManager;
use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};
use sqlx::{Pool, Postgres};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub enum AmountType {
    AVAILABLE,
    LOCKED,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Amount {
    available: Decimal,
    locked: Decimal,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserBalances {
    user_id: String,
    balance: HashMap<Asset, Amount>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct Engine {
    pub orderbooks: Vec<OrderBook>,
    pub balances: HashMap<String, Mutex<UserBalances>>,
}

impl Default for Engine {
    fn default() -> Self {
        Self::new()
    }
}

impl Engine {
    pub fn new() -> Engine {
        Engine {
            orderbooks: vec![],
            balances: HashMap::new(),
        }
    }

    pub async fn init_engine(&mut self, pool: &Pool<Postgres>) {
        let market = "SOL_USDC".to_string();
        let trade_id: i64 = get_latest_trade_id_from_db(pool, market).await.unwrap();

        let orderbook = OrderBook::new(
            AssetPair {
                base: Asset::SOL,
                quote: Asset::USDC,
            },
            trade_id + 1,
        );

        self.orderbooks.push(orderbook);
    }

    pub fn init_user_balance(&mut self, user_id: &str) {
        let initial_balances = UserBalances {
            user_id: user_id.to_string(),
            balance: HashMap::new(),
        };

        // Add dummy values for USDC and SOL
        let usdc_balance = Amount {
            available: Decimal::new(1000000, 0), // Dummy value: 1000000 USDC
            locked: Decimal::new(0, 0),          // 0 locked
        };

        let sol_balance = Amount {
            available: Decimal::new(10000, 0), // Dummy value: 10000 SOL
            locked: Decimal::new(0, 0),        // 0 locked
        };

        // Initialize the balance HashMap for the user
        let mut balances_map = initial_balances.balance;
        balances_map.insert(Asset::USDC, usdc_balance);
        balances_map.insert(Asset::SOL, sol_balance);

        // Add the initialized UserBalances to the Engine's balances map
        self.balances.insert(
            user_id.to_string(),
            Mutex::new(UserBalances {
                user_id: user_id.to_string(),
                balance: balances_map,
            }),
        );
    }

    /// PostgreSQL-based create_order (also deprecated - uses Decision Loop)
    #[deprecated(
        since = "0.2.0",
        note = "Use Shadow Engine via Decision Loop for risk-validated order execution"
    )]
    pub async fn create_order_pg(
        &mut self,
        input_order: CreateOrder,
        _pg_queue: &Arc<PgQueueManager>,
    ) -> Result<String, &str> {
        // DEPRECATION: Log warning and reject order
        eprintln!(
            "[DEPRECATED] Legacy Engine::create_order_pg() called for user {}. Orders must use Decision Loop.",
            input_order.user_id
        );

        // Return error to force callers to use the new path
        Err("Legacy engine deprecated. Use Decision Loop for order execution.")
    }

    pub fn get_open_order(&mut self, open_order: GetOpenOrder) -> Result<&Order, ()> {
        let orderbook = match self
            .orderbooks
            .iter_mut()
            .find(|orderbook| orderbook.ticker() == open_order.market)
        {
            Some(ob) => ob,
            None => {
                eprintln!(
                    "No matching orderbook found for market: {}",
                    open_order.market
                );
                return Err(());
            }
        };

        let open_order = orderbook.get_open_order(open_order.user_id, open_order.order_id);

        open_order
    }

    pub fn cancel_order(&mut self, cancel_order: CancelOrder) -> Result<String, &str> {
        let orderbook = match self
            .orderbooks
            .iter_mut()
            .find(|orderbook| orderbook.ticker() == cancel_order.market)
        {
            Some(ob) => ob,
            None => {
                eprintln!(
                    "No matching orderbook found for market: {}",
                    cancel_order.market
                );
                return Err("No matching orderbook found");
            }
        };

        let assets: Vec<&str> = cancel_order.market.split('_').collect();
        let base_asset_str = assets[0];
        let quote_asset_str = assets[1];
        let base_asset = Asset::parse(base_asset_str)?;
        let quote_asset = Asset::parse(quote_asset_str)?;
        let cancel_order_id = cancel_order.order_id.clone();

        let result = orderbook.cancel_order(cancel_order);

        match result {
            Ok(order) => {
                let quantity = match order.side {
                    OrderSide::BUY => (order.quantity - order.filled_quantity) * order.price,
                    OrderSide::SELL => order.quantity - order.filled_quantity,
                };

                match order.side {
                    OrderSide::BUY => {
                        self.update_balance_with_lock(
                            order.user_id.clone(),
                            quote_asset.clone(),
                            quantity,
                            AmountType::AVAILABLE,
                        )?;

                        self.update_balance_with_lock(
                            order.user_id.clone(),
                            quote_asset.clone(),
                            -quantity,
                            AmountType::LOCKED,
                        )?;
                    }

                    OrderSide::SELL => {
                        self.update_balance_with_lock(
                            order.user_id.clone(),
                            base_asset.clone(),
                            quantity,
                            AmountType::AVAILABLE,
                        )?;

                        self.update_balance_with_lock(
                            order.user_id.clone(),
                            base_asset.clone(),
                            -quantity,
                            AmountType::LOCKED,
                        )?;
                    }
                }

                Ok(cancel_order_id)
            }

            Err(()) => {
                println!("Failed to cancel order");
                Err("Failed to cancel order")
            }
        }
    }

    pub fn get_open_orders(&mut self, open_orders: GetOpenOrders) -> Vec<&Order> {
        let orderbook = match self
            .orderbooks
            .iter_mut()
            .find(|orderbook| orderbook.ticker() == open_orders.market)
        {
            Some(ob) => ob,
            None => {
                eprintln!(
                    "No matching orderbook found for market: {}",
                    open_orders.market
                );
                return Vec::new();
            }
        };

        let open_orders: Vec<&Order> = orderbook.get_open_orders(open_orders.user_id);

        open_orders
    }

    pub fn cancel_all_orders(
        &mut self,
        cancel_all_orders: CancelAllOrders,
    ) -> Result<String, &str> {
        let orderbook = match self
            .orderbooks
            .iter_mut()
            .find(|orderbook| orderbook.ticker() == cancel_all_orders.market)
        {
            Some(ob) => ob,
            None => {
                eprintln!(
                    "No matching orderbook found for market: {}",
                    cancel_all_orders.market
                );
                return Err("No matching orderbook found");
            }
        };

        let assets: Vec<&str> = cancel_all_orders.market.split('_').collect();
        let base_asset_str = assets[0];
        let quote_asset_str = assets[1];
        let base_asset = Asset::parse(base_asset_str)?;
        let quote_asset = Asset::parse(quote_asset_str)?;

        let open_orders = orderbook.cancel_all_orders(cancel_all_orders.user_id.clone());

        let mut balance_updates: Vec<(String, Asset, Decimal, AmountType)> = Vec::new();

        for order in open_orders {
            let quantity = match order.side {
                OrderSide::BUY => (order.quantity - order.filled_quantity) * order.price,
                OrderSide::SELL => order.quantity - order.filled_quantity,
            };

            match order.side {
                OrderSide::BUY => {
                    balance_updates.push((
                        order.user_id.clone(),
                        quote_asset.clone(),
                        quantity,
                        AmountType::AVAILABLE,
                    ));
                    balance_updates.push((
                        order.user_id.clone(),
                        quote_asset.clone(),
                        -quantity,
                        AmountType::LOCKED,
                    ));
                }

                OrderSide::SELL => {
                    balance_updates.push((
                        order.user_id.clone(),
                        base_asset.clone(),
                        quantity,
                        AmountType::AVAILABLE,
                    ));
                    balance_updates.push((
                        order.user_id.clone(),
                        base_asset.clone(),
                        -quantity,
                        AmountType::LOCKED,
                    ));
                }
            }
        }

        // Perform balance updates after the loop, ensuring only one mutable borrow of `self`
        for (user_id, asset, amount, amount_type) in balance_updates {
            self.update_balance_with_lock(user_id, asset, amount, amount_type)?;
        }

        // Return a success message after cancelling all orders
        Ok(format!(
            "All orders for user {} cancelled successfully",
            cancel_all_orders.user_id
        ))
    }

    pub fn get_depth(&self, depth: GetDepth) -> (Vec<(Decimal, Decimal)>, Vec<(Decimal, Decimal)>) {
        let orderbook = match self
            .orderbooks
            .iter()
            .find(|orderbook| orderbook.ticker() == depth.symbol)
        {
            Some(ob) => ob,
            None => {
                eprintln!("No matching orderbook found for market: {}", depth.symbol);
                return (Vec::new(), Vec::new());
            }
        };

        orderbook.get_depth()
    }

    pub fn check_and_lock_funds(&mut self, order: &CreateOrder) -> Result<(), &str> {
        let assets: Vec<&str> = order.market.split('_').collect();
        let base_asset_str = assets[0];
        let quote_asset_str = assets[1];

        // Convert string assets to Asset enum
        let base_asset = Asset::parse(base_asset_str)?;
        let quote_asset = Asset::parse(quote_asset_str)?;

        let user_id = &order.user_id;

        let user_balance_mutex = self
            .balances
            .get_mut(user_id)
            .ok_or("No matching user found")?;

        // Access the user's balances (using get_mut since we already have mutable access)
        let user_balance = user_balance_mutex
            .get_mut()
            .map_err(|_| "Mutex lock failed")?;

        match order.side {
            OrderSide::BUY => {
                let balance = user_balance
                    .balance
                    .get_mut(&quote_asset)
                    .ok_or("No balance for asset found")?;

                let total_cost = order.price * order.quantity;
                if balance.available >= total_cost {
                    balance.available -= total_cost;
                    balance.locked += total_cost;
                } else {
                    return Err("Insufficient funds");
                }
            }

            OrderSide::SELL => {
                // User must have order.quantity of base_asset
                let balance = user_balance
                    .balance
                    .get_mut(&base_asset)
                    .ok_or("No balance for asset found")?;

                if balance.available >= order.quantity {
                    balance.available -= order.quantity;
                    balance.locked += order.quantity;
                } else {
                    return Err("Insufficient asset quantity");
                }
            }
        }

        Ok(())
    }

    pub fn update_user_balance(
        &mut self,
        base_asset: Asset,
        quote_asset: Asset,
        order: Order,
        order_result: &ProcessOrderResult,
    ) -> Result<(), &str> {
        match order.side {
            OrderSide::BUY => {
                for fill in &order_result.fills {
                    // Update buyer's balances (current user)
                    self.update_balance_with_lock(
                        order.user_id.clone(),
                        base_asset.clone(),
                        fill.quantity,
                        AmountType::AVAILABLE,
                    )?;
                    self.update_balance_with_lock(
                        order.user_id.clone(),
                        quote_asset.clone(),
                        -(fill.price * fill.quantity),
                        AmountType::LOCKED,
                    )?;

                    // Update seller's balances (other user)
                    self.update_balance_with_lock(
                        fill.other_user_id.clone(),
                        quote_asset.clone(),
                        fill.price * fill.quantity,
                        AmountType::AVAILABLE,
                    )?;
                    self.update_balance_with_lock(
                        fill.other_user_id.clone(),
                        base_asset.clone(),
                        -fill.quantity,
                        AmountType::LOCKED,
                    )?;
                }
            }
            OrderSide::SELL => {
                for fill in &order_result.fills {
                    // Update seller's balances (current user)
                    self.update_balance_with_lock(
                        order.user_id.clone(),
                        base_asset.clone(),
                        -fill.quantity,
                        AmountType::LOCKED,
                    )?;
                    self.update_balance_with_lock(
                        order.user_id.clone(),
                        quote_asset.clone(),
                        fill.price * fill.quantity,
                        AmountType::AVAILABLE,
                    )?;

                    // Update buyer's balances (other user)
                    self.update_balance_with_lock(
                        fill.other_user_id.clone(),
                        base_asset.clone(),
                        fill.quantity,
                        AmountType::AVAILABLE,
                    )?;
                    self.update_balance_with_lock(
                        fill.other_user_id.clone(),
                        quote_asset.clone(),
                        -(fill.price * fill.quantity),
                        AmountType::LOCKED,
                    )?;
                }
            }
        }
        Ok(())
    }

    // Helper function to update balance with lock
    fn update_balance_with_lock(
        &self,
        user_id: String,
        asset: Asset,
        amount: Decimal,
        amount_type: AmountType,
    ) -> Result<(), &str> {
        // Access the user's balance via the Mutex
        let balances = &self.balances;
        let user_balance_mutex = balances.get(&user_id).ok_or("No matching user found")?;

        // Lock the Mutex to access the user's balances
        let mut user_balance = user_balance_mutex.lock().map_err(|_| "Mutex lock failed")?;

        let balance = user_balance
            .balance
            .get_mut(&asset)
            .ok_or("No balance for asset found")?;

        match amount_type {
            AmountType::AVAILABLE => balance.available += amount,
            AmountType::LOCKED => balance.locked += amount,
        }

        Ok(())
    }
}

use rust_decimal::Decimal;
use rust_decimal_macros::dec;
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap, HashSet};

use crate::types::engine::{AssetPair, CancelOrder, Fill, Order, OrderSide, ProcessOrderResult};

/// Order location for efficient order lookup and removal
#[derive(Debug, Clone, Serialize, Deserialize)]
struct OrderLocation {
    price: Decimal,
    side: OrderSide,
}

/// Order book with price-time priority matching
///
/// # Performance Optimizations (006-performance-overhaul)
///
/// - **FR-3.2: User Order Index** - `user_orders` index enables O(1) lookup of user's orders
/// - **FR-3.4: Range Matching** - Uses `BTreeMap::range()` for efficient price level matching
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OrderBook {
    pub bids: BTreeMap<Decimal, Vec<Order>>,
    pub asks: BTreeMap<Decimal, Vec<Order>>,
    pub asset_pair: AssetPair,
    pub trade_id: i64,
    last_update_id: i64,

    /// FR-3.2: Index of user_id -> order_ids for O(1) user order lookup
    /// This avoids scanning all orders when retrieving a user's open orders.
    #[serde(default)]
    user_orders: HashMap<String, HashSet<String>>,

    /// FR-3.2: Index of order_id -> location for O(1) order lookup
    /// Enables direct access to an order without scanning price levels.
    #[serde(default)]
    order_locations: HashMap<String, OrderLocation>,
}

impl OrderBook {
    pub fn new(asset_pair: AssetPair, trade_id: i64) -> OrderBook {
        OrderBook {
            asks: BTreeMap::new(),
            bids: BTreeMap::new(),
            asset_pair,
            trade_id,
            last_update_id: 0,
            user_orders: HashMap::new(),
            order_locations: HashMap::new(),
        }
    }

    /// FR-3.2.2: Add order to user index
    fn index_order(&mut self, order: &Order, side: OrderSide) {
        // Add to user_orders index
        self.user_orders
            .entry(order.user_id.clone())
            .or_default()
            .insert(order.order_id.clone());

        // Add to order_locations index
        self.order_locations.insert(
            order.order_id.clone(),
            OrderLocation {
                price: order.price,
                side,
            },
        );
    }

    /// FR-3.2.2: Remove order from user index
    fn unindex_order(&mut self, order: &Order) {
        // Remove from user_orders index
        if let Some(orders) = self.user_orders.get_mut(&order.user_id) {
            orders.remove(&order.order_id);
            if orders.is_empty() {
                self.user_orders.remove(&order.user_id);
            }
        }

        // Remove from order_locations index
        self.order_locations.remove(&order.order_id);
    }

    pub fn ticker(&self) -> String {
        format!("{:?}_{:?}", self.asset_pair.base, self.asset_pair.quote)
    }

    pub fn process_order(&mut self, mut order: Order) -> ProcessOrderResult {
        let order_result: ProcessOrderResult;

        match order.side {
            OrderSide::BUY => {
                order_result = self.match_asks(&order);
                order.filled_quantity = order_result.executed_quantity;
                if order_result.executed_quantity < order.quantity {
                    // FR-3.2.2: Index the order before adding to book
                    self.index_order(&order, OrderSide::BUY);
                    self.bids
                        .entry(order.price)
                        .and_modify(|orders| orders.push(order.clone()))
                        .or_insert(vec![order]);
                }
                order_result
            }
            OrderSide::SELL => {
                order_result = self.match_bids(&order);

                if order_result.executed_quantity < order.quantity {
                    // FR-3.2.2: Index the order before adding to book
                    self.index_order(&order, OrderSide::SELL);
                    self.asks
                        .entry(order.price)
                        .and_modify(|orders| orders.push(order.clone()))
                        .or_insert(vec![order]);
                }
                order_result
            }
        }
    }

    /// Match a buy order against asks
    ///
    /// FR-3.4.1: Uses `range(..=order.price)` to only iterate asks at or below the buy price.
    /// This is O(log n + k) where k is the number of matching price levels.
    pub fn match_asks(&mut self, order: &Order) -> ProcessOrderResult {
        let mut fills: Vec<Fill> = vec![];
        let mut executed_quantity: Decimal = dec!(0);
        let mut filled_order_ids: Vec<String> = vec![];

        // FR-3.4.1: Only iterate asks at prices <= buy order price
        // BTreeMap is sorted ascending, so range(..=price) gives us all asks we can match
        let matching_prices: Vec<Decimal> =
            self.asks.range(..=order.price).map(|(p, _)| *p).collect();

        for price in matching_prices {
            if let Some(asks) = self.asks.get_mut(&price) {
                for ask in asks.iter_mut() {
                    if executed_quantity >= order.quantity {
                        break;
                    }

                    let remaining = order.quantity - executed_quantity;
                    let available = ask.quantity - ask.filled_quantity;
                    let filled_quantity = std::cmp::min(remaining, available);

                    if filled_quantity > dec!(0) {
                        self.trade_id += 1;
                        executed_quantity += filled_quantity;
                        ask.filled_quantity += filled_quantity;

                        fills.push(Fill {
                            price: ask.price,
                            quantity: filled_quantity,
                            trade_id: self.trade_id,
                            other_user_id: ask.user_id.clone(),
                            order_id: ask.order_id.clone(),
                        });

                        // Track fully filled orders for index cleanup
                        if ask.filled_quantity >= ask.quantity {
                            filled_order_ids.push(ask.order_id.clone());
                        }
                    }
                }

                // Remove asks that have been completely filled
                asks.retain(|ask| ask.filled_quantity < ask.quantity);
            }
        }

        // FR-3.2.2 + AUD-02 FR-7: Clean up indexes for fully filled orders
        for fill in &fills {
            if filled_order_ids.contains(&fill.order_id) {
                self.order_locations.remove(&fill.order_id);
                if let Some(ids) = self.user_orders.get_mut(&fill.other_user_id) {
                    ids.remove(&fill.order_id);
                    if ids.is_empty() {
                        self.user_orders.remove(&fill.other_user_id);
                    }
                }
            }
        }

        // Clean up empty price levels
        self.asks.retain(|_, orders| !orders.is_empty());

        ProcessOrderResult {
            fills,
            executed_quantity,
        }
    }

    /// Match a sell order against bids
    ///
    /// FR-3.4.2: Uses `range(order.price..)` to only iterate bids at or above the sell price.
    /// This is O(log n + k) where k is the number of matching price levels.
    pub fn match_bids(&mut self, order: &Order) -> ProcessOrderResult {
        let mut fills: Vec<Fill> = vec![];
        let mut executed_quantity: Decimal = dec!(0);
        let mut filled_order_ids: Vec<String> = vec![];

        // FR-3.4.2: Only iterate bids at prices >= sell order price
        // BTreeMap is sorted ascending, so range(price..) gives bids at or above sell price
        // We reverse to match highest bids first (price-time priority)
        let matching_prices: Vec<Decimal> = self
            .bids
            .range(order.price..)
            .map(|(p, _)| *p)
            .rev()
            .collect();

        for price in matching_prices {
            if let Some(bids) = self.bids.get_mut(&price) {
                for bid in bids.iter_mut() {
                    if executed_quantity >= order.quantity {
                        break;
                    }

                    let remaining = order.quantity - executed_quantity;
                    let available = bid.quantity - bid.filled_quantity;
                    let filled_quantity = std::cmp::min(remaining, available);

                    if filled_quantity > dec!(0) {
                        self.trade_id += 1;
                        executed_quantity += filled_quantity;
                        bid.filled_quantity += filled_quantity;

                        fills.push(Fill {
                            price: bid.price,
                            quantity: filled_quantity,
                            trade_id: self.trade_id,
                            other_user_id: bid.user_id.clone(),
                            order_id: bid.order_id.clone(),
                        });

                        // Track fully filled orders for index cleanup
                        if bid.filled_quantity >= bid.quantity {
                            filled_order_ids.push(bid.order_id.clone());
                        }
                    }
                }

                // Remove bids that have been completely filled
                bids.retain(|bid| bid.filled_quantity < bid.quantity);
            }
        }

        // FR-3.2.2 + AUD-02 FR-7: Clean up indexes for fully filled orders
        for fill in &fills {
            if filled_order_ids.contains(&fill.order_id) {
                self.order_locations.remove(&fill.order_id);
                if let Some(ids) = self.user_orders.get_mut(&fill.other_user_id) {
                    ids.remove(&fill.order_id);
                    if ids.is_empty() {
                        self.user_orders.remove(&fill.other_user_id);
                    }
                }
            }
        }

        // Clean up empty price levels
        self.bids.retain(|_, orders| !orders.is_empty());

        ProcessOrderResult {
            fills,
            executed_quantity,
        }
    }

    pub fn get_open_order(&self, user_id: String, order_id: String) -> Result<&Order, ()> {
        let order = self
            .bids
            .values()
            .chain(self.asks.values()) // Combine bids and asks
            .flat_map(|orders| orders.iter()) // Flatten the Vec<Order> for each price level
            .find(|order| order.user_id == user_id && order.order_id == order_id);

        match order {
            Some(order) => Ok(order),
            None => Err(()),
        }
    }

    /// Get all open orders for a user
    ///
    /// FR-3.2.3: Uses user_orders index for O(k) lookup where k is the user's order count.
    /// Previously O(n) where n is total orders in the book.
    pub fn get_open_orders(&self, user_id: String) -> Vec<&Order> {
        // FR-3.2.3: Use index for efficient lookup
        let order_ids = match self.user_orders.get(&user_id) {
            Some(ids) => ids,
            None => return vec![],
        };

        let mut orders = Vec::with_capacity(order_ids.len());

        for order_id in order_ids {
            // Use order_locations to find the order directly
            if let Some(location) = self.order_locations.get(order_id) {
                let book = match location.side {
                    OrderSide::BUY => &self.bids,
                    OrderSide::SELL => &self.asks,
                };

                if let Some(orders_at_price) = book.get(&location.price) {
                    if let Some(order) = orders_at_price.iter().find(|o| &o.order_id == order_id) {
                        orders.push(order);
                    }
                }
            }
        }

        orders
    }

    /// Cancel a specific order
    ///
    /// FR-3.2.2: Maintains user_orders and order_locations indexes.
    pub fn cancel_order(&mut self, cancel_order: CancelOrder) -> Result<Order, ()> {
        let (order, should_remove_price) = {
            let orders_map = match cancel_order.side {
                OrderSide::BUY => &mut self.bids,
                OrderSide::SELL => &mut self.asks,
            };

            if let Some(orders) = orders_map.get_mut(&cancel_order.price) {
                if let Some(index) = orders
                    .iter()
                    .position(|order| order.order_id == cancel_order.order_id)
                {
                    let order = orders.remove(index);
                    let should_remove = orders.is_empty();
                    (Some(order), should_remove)
                } else {
                    (None, false)
                }
            } else {
                (None, false)
            }
        };

        match order {
            Some(order) => {
                // FR-3.2.2: Update indexes
                self.unindex_order(&order);

                // Clean up empty price level
                if should_remove_price {
                    match cancel_order.side {
                        OrderSide::BUY => self.bids.remove(&cancel_order.price),
                        OrderSide::SELL => self.asks.remove(&cancel_order.price),
                    };
                }

                Ok(order)
            }
            None => Err(()),
        }
    }

    /// Cancel all orders for a user
    ///
    /// FR-3.2.2: Uses user_orders index for efficient cancellation.
    /// Returns empty vec since all orders are now cancelled.
    pub fn cancel_all_orders(&mut self, user_id: String) -> Vec<&Order> {
        // FR-3.2.3: Use index to find all user's orders
        let order_ids: Vec<String> = self
            .user_orders
            .get(&user_id)
            .map(|ids| ids.iter().cloned().collect())
            .unwrap_or_default();

        // Remove each order using the index
        for order_id in order_ids {
            if let Some(location) = self.order_locations.remove(&order_id) {
                let orders_map = match location.side {
                    OrderSide::BUY => &mut self.bids,
                    OrderSide::SELL => &mut self.asks,
                };

                if let Some(orders) = orders_map.get_mut(&location.price) {
                    orders.retain(|o| o.order_id != order_id);
                    if orders.is_empty() {
                        orders_map.remove(&location.price);
                    }
                }
            }
        }

        // Clear user's entry from user_orders index
        self.user_orders.remove(&user_id);

        // Return empty vec - all orders cancelled
        vec![]
    }

    pub fn get_depth(&self) -> (Vec<(Decimal, Decimal)>, Vec<(Decimal, Decimal)>) {
        let mut bids_depth: Vec<(Decimal, Decimal)> = Vec::new();
        let mut asks_depth: Vec<(Decimal, Decimal)> = Vec::new();

        // Aggregate quantities for each price level in bids
        for (price, orders) in self.bids.iter() {
            let total_quantity = orders
                .iter()
                .fold(Decimal::ZERO, |acc, order| acc + order.quantity);
            bids_depth.push((*price, total_quantity));
        }

        // Aggregate quantities for each price level in asks
        for (price, orders) in self.asks.iter() {
            let total_quantity = orders
                .iter()
                .fold(Decimal::ZERO, |acc, order| acc + order.quantity);
            asks_depth.push((*price, total_quantity));
        }

        (bids_depth, asks_depth)
    }
}

use crate::{types::engine::OrderRequests, Engine};
use pg_queue::PgQueueManager;
use std::sync::Arc;
use tokio::sync::Mutex;

/// Handle order requests from PostgreSQL queue
/// Uses pg_notify for responses instead of Redis pub/sub
pub async fn handle_order_pg(
    payload: serde_json::Value,
    pg_queue: &Arc<PgQueueManager>,
    engine: Arc<Mutex<Engine>>,
) {
    match serde_json::from_value::<OrderRequests>(payload) {
        Ok(order) => match order {
            OrderRequests::CreateOrder(order) => {
                println!("Create Order: {:?}", order);
                let pubsub_id = match order.pubsub_id {
                    Some(id) => id.to_string(),
                    None => {
                        eprintln!("CreateOrder missing pubsub_id, cannot respond");
                        return;
                    }
                };

                let response = {
                    let mut engine_guard = engine.lock().await;
                    match engine_guard.create_order_pg(order, pg_queue).await {
                        Ok(order_id) => {
                            println!("Successfully placed order!");
                            serde_json::json!({
                                "status": "Created Order",
                                "order_id": order_id,
                            })
                        }
                        Err(err) => {
                            println!("Order creation failed - {}", err);
                            serde_json::json!({
                                "status": "Failed to Create Order",
                            })
                        }
                    }
                };

                if let Ok(response_string) = serde_json::to_string(&response) {
                    let _ = pg_queue.notify.notify(&pubsub_id, &response_string).await;
                }
            }

            OrderRequests::GetOpenOrder(open_order) => {
                println!("Get Open Order: {:?}", open_order);
                let pubsub_id = match open_order.pubsub_id {
                    Some(id) => id.to_string(),
                    None => {
                        eprintln!("GetOpenOrder missing pubsub_id, cannot respond");
                        return;
                    }
                };

                let response = {
                    let mut engine_guard = engine.lock().await;
                    match engine_guard.get_open_order(open_order) {
                        Ok(open_order) => {
                            println!("Successfully retrieved open order!");
                            serde_json::json!(open_order)
                        }
                        Err(()) => {
                            println!("Order retrieval failed");
                            serde_json::json!({
                                "status": "Failed to Retrieve Open Order",
                            })
                        }
                    }
                };

                if let Ok(response_string) = serde_json::to_string(&response) {
                    let _ = pg_queue.notify.notify(&pubsub_id, &response_string).await;
                }
            }

            OrderRequests::CancelOrder(cancel_order) => {
                println!("Cancel Order: {:?}", cancel_order);
                let pubsub_id = match cancel_order.pubsub_id {
                    Some(id) => id.to_string(),
                    None => {
                        eprintln!("CancelOrder missing pubsub_id, cannot respond");
                        return;
                    }
                };

                let response = {
                    let mut engine_guard = engine.lock().await;
                    match engine_guard.cancel_order(cancel_order) {
                        Ok(cancel_order_id) => {
                            println!("Successfully cancelled order!");
                            serde_json::json!({
                                "status": "Cancelled Order",
                                "order_id": cancel_order_id,
                            })
                        }
                        Err(err) => {
                            println!("Order cancellation failed - {}", err);
                            serde_json::json!({
                                "status": "Failed to Cancel Order",
                            })
                        }
                    }
                };

                if let Ok(response_string) = serde_json::to_string(&response) {
                    let _ = pg_queue.notify.notify(&pubsub_id, &response_string).await;
                }
            }

            OrderRequests::GetOpenOrders(open_orders) => {
                println!("Open Order: {:?}", open_orders);
                let pubsub_id = match open_orders.pubsub_id {
                    Some(id) => id.to_string(),
                    None => {
                        eprintln!("GetOpenOrders missing pubsub_id, cannot respond");
                        return;
                    }
                };

                // Serialize while holding the lock since get_open_orders returns references
                let response_string = {
                    let mut engine_guard = engine.lock().await;
                    let open_orders_vec = engine_guard.get_open_orders(open_orders);
                    serde_json::to_string(&open_orders_vec)
                };

                if let Ok(response_string) = response_string {
                    let _ = pg_queue.notify.notify(&pubsub_id, &response_string).await;
                }
                println!("Successfully retrieved open orders!");
            }

            OrderRequests::CancelAllOrders(cancel_all_orders) => {
                println!("Cancel All Orders: {:?}", cancel_all_orders);
                let user_id = cancel_all_orders.user_id.clone();
                let pubsub_id = match cancel_all_orders.pubsub_id {
                    Some(id) => id.to_string(),
                    None => {
                        eprintln!("CancelAllOrders missing pubsub_id, cannot respond");
                        return;
                    }
                };

                let response = {
                    let mut engine_guard = engine.lock().await;
                    match engine_guard.cancel_all_orders(cancel_all_orders) {
                        Ok(_) => {
                            println!("Successfully cancelled all orders!");
                            serde_json::json!({
                                "status": "Cancelled All Orders",
                                "user_id": user_id,
                            })
                        }
                        Err(err) => {
                            println!("Order cancellation failed - {}", err);
                            serde_json::json!({
                                "status": "Failed to Cancel All Orders",
                            })
                        }
                    }
                };

                if let Ok(response_string) = serde_json::to_string(&response) {
                    let _ = pg_queue.notify.notify(&pubsub_id, &response_string).await;
                }
            }

            OrderRequests::GetDepth(depth) => {
                println!("Get Depth: {:?}", depth);
                let pubsub_id = match depth.pubsub_id {
                    Some(id) => id.to_string(),
                    None => {
                        eprintln!("GetDepth missing pubsub_id, cannot respond");
                        return;
                    }
                };

                let depth_result = {
                    let engine_guard = engine.lock().await;
                    engine_guard.get_depth(depth)
                };

                let depth_json = serde_json::json!({
                    "bids": depth_result.0,
                    "asks": depth_result.1,
                });

                if let Ok(response_string) = serde_json::to_string(&depth_json) {
                    let _ = pg_queue.notify.notify(&pubsub_id, &response_string).await;
                }
                println!("Successfully retrieved depth!");
            }
        },
        Err(err) => {
            println!("Failed to deserialize order request: {:?}", err);
        }
    }
}

//! Shadow Order Management
//!
//! Manages virtual orders for paper trading. Orders are checked against
//! live market data and filled when conditions are met.
//!
//! # Fill Logic (from PRD)
//!
//! - **Buy Limit**: Fills if `Low Price <= Limit Price`
//! - **Sell Limit**: Fills if `High Price >= Limit Price`
//! - **Buy Market**: Fills immediately at `Best Ask`
//! - **Sell Market**: Fills immediately at `Best Bid`
//! - **Stop Loss Buy**: Triggers when `High Price >= Stop Price`
//! - **Stop Loss Sell**: Triggers when `Low Price <= Stop Price`

use chrono::{DateTime, Utc};
use rust_decimal::Decimal;
use rust_decimal_macros::dec;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::time::Instant;
use uuid::Uuid;

use super::ShadowEngineError;

/// Order side - buy or sell
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ShadowOrderSide {
    Buy,
    Sell,
}

/// Order type
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ShadowOrderType {
    Market,
    Limit,
    StopLoss,
    TakeProfit,
}

/// Order status
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ShadowOrderStatus {
    Open,
    Filled,
    PartiallyFilled,
    Cancelled,
    Rejected,
}

/// A shadow (paper trading) order
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ShadowOrder {
    pub id: Uuid,
    pub user_id: Uuid,
    pub symbol: String,
    pub side: ShadowOrderSide,
    pub order_type: ShadowOrderType,
    pub quantity: Decimal,
    pub filled_quantity: Decimal,
    pub price: Option<Decimal>,      // For limit orders
    pub stop_price: Option<Decimal>, // For stop/take-profit orders
    pub average_fill_price: Option<Decimal>,
    pub status: ShadowOrderStatus,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    pub filled_at: Option<DateTime<Utc>>,

    // Optional linked orders for trade management
    pub stop_loss_price: Option<Decimal>,
    pub take_profit_price: Option<Decimal>,
    pub parent_order_id: Option<Uuid>,

    /// Risk validation flag - must be true for order to be accepted by Shadow Engine.
    /// Set to true by the Decision Loop after risk validation passes.
    /// Orders with risk_validated = false will be rejected by ShadowEngine::place_order().
    #[serde(default)]
    pub risk_validated: bool,

    /// Leverage multiplier for margin calculation (1 = no leverage).
    /// Margin required = notional / leverage. Per-pair limits enforced at exchange.
    #[serde(default = "default_leverage")]
    pub leverage: u8,

    /// AUD-02: Timestamp when order reached terminal state (for GC).
    #[serde(skip)]
    pub completed_at: Option<Instant>,
}

fn default_leverage() -> u8 {
    1
}

impl ShadowOrder {
    /// Create a new shadow order
    ///
    /// Note: Orders are created with `risk_validated = false` by default.
    /// Use `mark_risk_validated()` after passing Decision Loop validation.
    pub fn new(
        user_id: Uuid,
        symbol: String,
        side: ShadowOrderSide,
        order_type: ShadowOrderType,
        quantity: Decimal,
        price: Option<Decimal>,
        stop_price: Option<Decimal>,
        parent_order_id: Option<Uuid>,
    ) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4(),
            user_id,
            symbol,
            side,
            order_type,
            quantity,
            filled_quantity: dec!(0),
            price,
            stop_price,
            average_fill_price: None,
            status: ShadowOrderStatus::Open,
            created_at: now,
            updated_at: now,
            filled_at: None,
            stop_loss_price: None,
            take_profit_price: None,
            parent_order_id,
            risk_validated: false,
            leverage: 1,
            completed_at: None,
        }
    }

    /// Mark this order as risk-validated.
    ///
    /// Called by the Decision Loop after the order passes risk checks.
    /// Orders must have `risk_validated = true` to be accepted by Shadow Engine.
    pub fn mark_risk_validated(&mut self) {
        self.risk_validated = true;
        log::info!(
            "Order {} marked as risk validated (symbol={}, side={:?}, qty={})",
            self.id,
            self.symbol,
            self.side,
            self.quantity
        );
    }

    /// Check if this order has been risk-validated
    pub fn is_risk_validated(&self) -> bool {
        self.risk_validated
    }

    /// Create a market buy order
    pub fn market_buy(user_id: Uuid, symbol: &str, quantity: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Buy,
            ShadowOrderType::Market,
            quantity,
            None,
            None,
            None,
        )
    }

    /// Create a market sell order
    pub fn market_sell(user_id: Uuid, symbol: &str, quantity: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Sell,
            ShadowOrderType::Market,
            quantity,
            None,
            None,
            None,
        )
    }

    /// Create a limit buy order
    pub fn limit_buy(user_id: Uuid, symbol: &str, quantity: Decimal, price: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Buy,
            ShadowOrderType::Limit,
            quantity,
            Some(price),
            None,
            None,
        )
    }

    /// Create a limit sell order
    pub fn limit_sell(user_id: Uuid, symbol: &str, quantity: Decimal, price: Decimal) -> Self {
        Self::new(
            user_id,
            symbol.to_string(),
            ShadowOrderSide::Sell,
            ShadowOrderType::Limit,
            quantity,
            Some(price),
            None,
            None,
        )
    }

    /// Get the asset required for this order (futures: always quote currency margin).
    /// Normalizes "USD" → "USDT" since perpetual futures margin is always USDT.
    pub fn required_asset(&self) -> String {
        let (_base, quote) = self.symbol_parts();
        // Perpetual futures: "USD" pairs settle in USDT
        if quote == "USD" {
            "USDT".to_string()
        } else {
            quote
        }
    }

    /// Get the margin required for this order (futures: notional / leverage)
    pub fn required_amount(&self) -> Decimal {
        let price = self.price.unwrap_or(dec!(0));
        let notional = self.quantity * price;
        notional / Decimal::from(self.leverage.max(1))
    }

    /// Parse symbol into base and quote assets
    pub fn symbol_parts(&self) -> (String, String) {
        let parts: Vec<&str> = self.symbol.split('_').collect();
        if parts.len() == 2 {
            (parts[0].to_string(), parts[1].to_string())
        } else {
            // Fallback for symbols like "BTCUSDC"
            // Assume last 4 chars are quote for USDC/USDT
            if self.symbol.ends_with("USDC") {
                let base = &self.symbol[..self.symbol.len() - 4];
                (base.to_string(), "USDC".to_string())
            } else if self.symbol.ends_with("USDT") {
                let base = &self.symbol[..self.symbol.len() - 4];
                (base.to_string(), "USDT".to_string())
            } else {
                (self.symbol.clone(), "USDC".to_string())
            }
        }
    }

    /// Check if this order should fill at the given market prices.
    ///
    /// Uses current bid/ask for real-time fill checking (live price feed).
    /// - bid = best price someone will buy at (what you get when selling)
    /// - ask = best price someone will sell at (what you pay when buying)
    pub fn should_fill(&self, bid: Decimal, ask: Decimal, _high: Decimal, _low: Decimal) -> bool {
        match (&self.order_type, &self.side) {
            // Market orders fill immediately
            (ShadowOrderType::Market, _) => true,

            // Limit buy fills when ask drops to or below limit price
            (ShadowOrderType::Limit, ShadowOrderSide::Buy) => {
                self.price.map(|p| ask <= p).unwrap_or(false)
            }

            // Limit sell fills when bid rises to or above limit price
            (ShadowOrderType::Limit, ShadowOrderSide::Sell) => {
                self.price.map(|p| bid >= p).unwrap_or(false)
            }

            // Stop loss buy (short SL) triggers when ask rises to stop price
            (ShadowOrderType::StopLoss, ShadowOrderSide::Buy) => {
                self.stop_price.map(|p| ask >= p).unwrap_or(false)
            }

            // Stop loss sell (long SL) triggers when bid drops to stop price
            (ShadowOrderType::StopLoss, ShadowOrderSide::Sell) => {
                self.stop_price.map(|p| bid <= p).unwrap_or(false)
            }

            // Take profit buy (short TP) triggers when ask drops to target
            (ShadowOrderType::TakeProfit, ShadowOrderSide::Buy) => {
                self.stop_price.map(|p| ask <= p).unwrap_or(false)
            }

            // Take profit sell (long TP) triggers when bid rises to target
            (ShadowOrderType::TakeProfit, ShadowOrderSide::Sell) => {
                self.stop_price.map(|p| bid >= p).unwrap_or(false)
            }
        }
    }

    /// Fill this order at the given price
    pub fn fill(&mut self, fill_price: Decimal) {
        self.filled_quantity = self.quantity;
        self.average_fill_price = Some(fill_price);
        self.status = ShadowOrderStatus::Filled;
        self.filled_at = Some(Utc::now());
        self.updated_at = Utc::now();
        self.completed_at = Some(Instant::now());
    }

    /// Cancel this order
    pub fn cancel(&mut self) {
        self.status = ShadowOrderStatus::Cancelled;
        self.updated_at = Utc::now();
        self.completed_at = Some(Instant::now());
    }

    /// Check if order is still open
    pub fn is_open(&self) -> bool {
        matches!(
            self.status,
            ShadowOrderStatus::Open | ShadowOrderStatus::PartiallyFilled
        )
    }

    /// Set leverage for this order (affects margin calculation)
    pub fn with_leverage(mut self, leverage: u8) -> Self {
        self.leverage = leverage.max(1);
        self
    }

    /// Set stop loss price for this order
    pub fn with_stop_loss(mut self, price: Decimal) -> Self {
        self.stop_loss_price = Some(price);
        self
    }

    /// Set take profit price for this order
    pub fn with_take_profit(mut self, price: Decimal) -> Self {
        self.take_profit_price = Some(price);
        self
    }
}

/// Manages all shadow orders
pub struct ShadowOrderManager {
    /// All orders by ID
    orders: HashMap<Uuid, ShadowOrder>,
    /// Index of orders by user
    orders_by_user: HashMap<Uuid, Vec<Uuid>>,
    /// Index of open orders by symbol
    open_orders_by_symbol: HashMap<String, Vec<Uuid>>,
}

impl Default for ShadowOrderManager {
    fn default() -> Self {
        Self::new()
    }
}

impl ShadowOrderManager {
    pub fn new() -> Self {
        Self {
            orders: HashMap::new(),
            orders_by_user: HashMap::new(),
            open_orders_by_symbol: HashMap::new(),
        }
    }

    /// Add a new order
    pub fn add_order(&mut self, user_id: Uuid, mut order: ShadowOrder) -> ShadowOrder {
        order.user_id = user_id;
        let order_id = order.id;
        let symbol = order.symbol.clone();

        // Store the order
        self.orders.insert(order_id, order.clone());

        // Index by user
        self.orders_by_user
            .entry(user_id)
            .or_default()
            .push(order_id);

        // Index open orders by symbol
        if order.is_open() {
            self.open_orders_by_symbol
                .entry(symbol)
                .or_default()
                .push(order_id);
        }

        order
    }

    /// Get all open orders for a user
    pub fn get_open_orders(&self, user_id: Uuid) -> Vec<ShadowOrder> {
        self.orders_by_user
            .get(&user_id)
            .map(|order_ids| {
                order_ids
                    .iter()
                    .filter_map(|id| self.orders.get(id))
                    .filter(|o| o.is_open())
                    .cloned()
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Get all orders for a user (including filled/cancelled)
    pub fn get_all_orders(&self, user_id: Uuid) -> Vec<ShadowOrder> {
        self.orders_by_user
            .get(&user_id)
            .map(|order_ids| {
                order_ids
                    .iter()
                    .filter_map(|id| self.orders.get(id))
                    .cloned()
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Get a specific order
    pub fn get_order(&self, order_id: Uuid) -> Option<&ShadowOrder> {
        self.orders.get(&order_id)
    }

    /// Cancel an order
    pub fn cancel_order(
        &mut self,
        user_id: Uuid,
        order_id: Uuid,
    ) -> Result<ShadowOrder, ShadowEngineError> {
        let order = self
            .orders
            .get_mut(&order_id)
            .ok_or(ShadowEngineError::OrderNotFound(order_id))?;

        if order.user_id != user_id {
            return Err(ShadowEngineError::OrderNotFound(order_id));
        }

        if !order.is_open() {
            return Err(ShadowEngineError::InvalidOrder(
                "Order is not open".to_string(),
            ));
        }

        order.cancel();

        // Remove from open orders index
        if let Some(ids) = self.open_orders_by_symbol.get_mut(&order.symbol) {
            ids.retain(|id| *id != order_id);
        }

        Ok(order.clone())
    }

    /// Check for orders that should fill at current prices (READ-ONLY)
    ///
    /// Returns copies of orders that would trigger at the given prices.
    /// Does NOT modify any state - use `apply_fills` to actually fill orders.
    ///
    /// Part of the Read-Compute-Write pattern (004-read-compute-write):
    /// - READ: This method - identify triggerable orders without locking
    /// - COMPUTE: Calculate fills in memory
    /// - WRITE: `apply_fills` - update state atomically
    pub fn get_triggerable_orders(
        &self,
        symbol: &str,
        bid: Decimal,
        ask: Decimal,
        high: Decimal,
        low: Decimal,
    ) -> Vec<ShadowOrder> {
        let order_ids: Vec<Uuid> = self
            .open_orders_by_symbol
            .get(symbol)
            .cloned()
            .unwrap_or_default();

        order_ids
            .iter()
            .filter_map(|order_id| self.orders.get(order_id))
            .filter(|order| order.should_fill(bid, ask, high, low))
            .cloned()
            .collect()
    }

    /// Apply fills to orders (WRITE operation)
    ///
    /// Marks orders as filled and removes them from the open orders index.
    /// Part of the Read-Compute-Write pattern - call after computing fills.
    pub fn apply_fills(&mut self, order_ids: &[Uuid]) {
        for order_id in order_ids {
            if let Some(order) = self.orders.get(order_id) {
                let symbol = order.symbol.clone();

                // Remove from open orders index
                if let Some(ids) = self.open_orders_by_symbol.get_mut(&symbol) {
                    ids.retain(|id| id != order_id);
                }
            }

            // Update the order status
            if let Some(stored_order) = self.orders.get_mut(order_id) {
                stored_order.status = ShadowOrderStatus::Filled;
                stored_order.completed_at = Some(Instant::now());
            }
        }
    }

    /// Check for orders that should fill at current prices
    ///
    /// Returns orders that have been filled (removed from open orders)
    ///
    /// DEPRECATED: Use `get_triggerable_orders` + `apply_fills` for the
    /// Read-Compute-Write pattern which minimizes lock contention.
    pub fn check_fills(
        &mut self,
        symbol: &str,
        bid: Decimal,
        ask: Decimal,
        high: Decimal,
        low: Decimal,
    ) -> Vec<ShadowOrder> {
        let mut filled = Vec::new();

        let order_ids: Vec<Uuid> = self
            .open_orders_by_symbol
            .get(symbol)
            .cloned()
            .unwrap_or_default();

        for order_id in order_ids {
            if let Some(order) = self.orders.get(&order_id) {
                if order.should_fill(bid, ask, high, low) {
                    filled.push(order.clone());
                }
            }
        }

        // Remove filled orders from the open index
        for order in &filled {
            if let Some(ids) = self.open_orders_by_symbol.get_mut(&order.symbol) {
                ids.retain(|id| *id != order.id);
            }
            // Update the order status in our storage
            if let Some(stored_order) = self.orders.get_mut(&order.id) {
                stored_order.status = ShadowOrderStatus::Filled;
                stored_order.completed_at = Some(Instant::now());
            }
        }

        filled
    }

    /// Get all symbols that currently have open orders
    ///
    /// Used by PriceFeedService to know which symbols need price polling.
    /// Returns a deduplicated list of symbols with at least one open order.
    pub fn get_active_symbols(&self) -> Vec<String> {
        self.open_orders_by_symbol
            .iter()
            .filter(|(_, ids)| !ids.is_empty())
            .map(|(symbol, _)| symbol.clone())
            .collect()
    }

    /// Get count of open orders
    pub fn open_order_count(&self) -> usize {
        self.orders.values().filter(|o| o.is_open()).count()
    }

    /// AUD-02 FR-1: Remove terminal orders older than cutoff.
    pub fn prune_terminal(&mut self, cutoff: Instant) -> usize {
        let to_remove: Vec<Uuid> = self
            .orders
            .iter()
            .filter(|(_, o)| {
                !o.is_open() && o.completed_at.is_some_and(|t| t < cutoff)
            })
            .map(|(id, _)| *id)
            .collect();

        for id in &to_remove {
            self.orders.remove(id);
        }

        // Clean orders_by_user
        for ids in self.orders_by_user.values_mut() {
            ids.retain(|id| !to_remove.contains(id));
        }

        to_remove.len()
    }

    /// Update the stop price of an existing order (for break-even)
    pub fn update_stop_price(&mut self, order_id: Uuid, new_stop_price: Decimal) -> bool {
        if let Some(order) = self.orders.get_mut(&order_id) {
            order.stop_price = Some(new_stop_price);
            order.updated_at = chrono::Utc::now();
            true
        } else {
            false
        }
    }
}

#[cfg(test)]
