        // Margin = 20323.8 / 27 = 752.73333...
        let order =
            ShadowOrder::limit_buy(user_id, "BTC_USDT", dec!(0.3), dec!(67746)).with_leverage(27);
        assert_eq!(order.leverage, 27);

        let margin = order.required_amount();
        // 20323.8 / 27 = 752.7333...
        assert!(
