        let mut manager = ShadowOrderManager::new();
        let user_id = Uuid::new_v4();

        manager.add_order(
            user_id,
            ShadowOrder::limit_buy(user_id, "BTC_USDT", dec!(0.1), dec!(50000)),
        );

